/*
 * A183232  Second of two complementary trees generated by the triangular
 *          numbers. The other tree is A183231.
 * https://oeis.org/A183232
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   not stated
 * Range:     u8 n <= 4, u16 n <= 15, u32 n <= 31, u64 n <= 40, u128 n <= 40,
 *            big any n
 * Helpers:   floor_sqrt
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A183232 – second complementary tree generated by the triangular numbers
 *  Recurrence:
 *     a(1)         = 2;
 *     For n > 1 let p = ⌊n/2⌋.
 *     If n is even (left child):
 *          a(n) = a(p) + T(a(p)+1)          (T(m)=m*(m+1)/2)
 *     If n is odd  (right child):
 *          let v = a(p)
 *          compute k = ⌊(√(8v+1)-1)/2⌋
 *          if v = T(k+1)-1 then
 *                a(n) = v + (k+2)
 *          else
 *                a(n) = v + (k+1)
 */

#include <stddef.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/floor_sqrt.h"

static seq_t *cache = NULL;          /* 1‑based index; cache[0] unused */
static idx_t  cache_size = 0;        /* current allocated size */

static void ensure_cache(idx_t n)
{
    if (cache_size <= n) {
        idx_t new_size = n * 2 + 1;      /* extra space for future growth   */
        seq_t *new_cache =
            (seq_t *)realloc(cache, (size_t)new_size * sizeof(seq_t));
        if (new_cache == NULL)
            abort();                     /* out of memory */
        cache = new_cache;
        /* initialise the newly allocated part to 0 (emptied value) */
        for (idx_t i = cache_size; i < new_size; ++i)
            cache[i] = 0;
        cache_size = new_size;
    }
}

static seq_t rec(idx_t n)
{
    ensure_cache(n);
    if (cache[n] != 0)            /* already computed (never 0 in this seq.) */
        return cache[n];

    if (n == 1) {                 /* base case */
        cache[1] = 2;
        return 2;
    }

    idx_t p   = n >> 1;           /* parent index */
    seq_t vp  = rec(p);           /* parent value  */
    seq_t ans;

    if ((n & 1) == 0) {           /* left child */
        seq_t tl = (vp + 1) * (vp + 2) / 2; /* T(vp+1) */
        ans = vp + tl;
    } else {                      /* right child */
        seq_t tmp = vp * 8 + 1;
        seq_t s   = floor_sqrt(tmp);
        seq_t k   = (s - 1) / 2;          /* k = floor((sqrt(8*vp+1)-1)/2) */

        seq_t tk1 = (k + 1) * (k + 2) / 2; /* T(k+1) */
        seq_t diff = (vp == tk1 - 1) ? (k + 2) : (k + 1);
        ans = vp + diff;
    }

    cache[n] = ans;
    return ans;
}

seq_t a(idx_t n)
{
    return rec(n);
}
